import type { Metadata } from "next";
import {
  COMPANY,
  DEFAULT_LOCALE,
  LOCALES,
  LOCALE_TAGS,
  SITE_URL,
  absoluteUrl,
  path,
  type Locale,
  type RouteKey,
} from "@/content/site";
import { getDictionary } from "@/content/locales";

type SeoKey = keyof ReturnType<typeof getDictionary>["seo"];

/**
 * The social card generated by `src/app/opengraph-image.tsx`, republished as a
 * real .png by `scripts/postbuild.mjs` so GitHub Pages serves the right
 * content type.
 */
const OG_IMAGE = {
  url: `${SITE_URL}/og.png`,
  width: 1200,
  height: 630,
  alt: `${COMPANY.name} — ${COMPANY.expansion}`,
};

/** Open Graph locale codes, which differ slightly from BCP-47 tags. */
const OG_LOCALES: Record<Locale, string> = {
  uk: "uk_UA",
  en: "en_US",
  ru: "ru_RU",
};

/**
 * Builds the full metadata block for a localized page: canonical URL,
 * hreflang alternates (including x-default), Open Graph and Twitter cards.
 */
export function buildMetadata(
  locale: Locale,
  route: RouteKey,
  seoKey: SeoKey = route as SeoKey,
): Metadata {
  const dict = getDictionary(locale);
  const seo = dict.seo[seoKey];
  const pathname = path(locale, route);
  const url = absoluteUrl(pathname);

  const languages: Record<string, string> = {};
  for (const alt of LOCALES) {
    languages[LOCALE_TAGS[alt]] = absoluteUrl(path(alt, route));
  }
  languages["x-default"] = absoluteUrl(path(DEFAULT_LOCALE, route));

  return {
    title: seo.title,
    description: seo.description,
    keywords: seo.keywords,
    alternates: {
      canonical: url,
      languages,
    },
    openGraph: {
      type: "website",
      siteName: COMPANY.name,
      title: seo.title,
      description: seo.description,
      url,
      locale: OG_LOCALES[locale],
      alternateLocale: LOCALES.filter((l) => l !== locale).map(
        (l) => OG_LOCALES[l],
      ),
      images: [OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: seo.title,
      description: seo.description,
      images: [OG_IMAGE.url],
    },
  };
}
